from pathlib import Path
import json
from datetime import datetime, timezone

D = Path(__file__).resolve().parent
ROOT = D.parents[6]
goals = json.loads((D/'current20-whole-DEEN-goals.actual.json').read_text())['goals']
def pair(de,en): return {'de':de,'en':en}
def case(material,task,answer,boundary=None):
    return {'material':material,'task':task,'modelAnswer':answer,'performanceBoundary':boundary or pair('Eigenes ausdrücklich synthetisches Modellmaterial; keine reale Erhebung, kein Nachweis einer Leistung lernender Personen.','Original explicitly synthetic model material; no real survey or evidence of learner performance.')}

CASES = [
[
 case(pair('Eigenes Wiesenmodell: Gras wird von Heuschrecken und Mäusen gefressen; Frösche fressen Heuschrecken, Störche fressen Frösche und Mäuse. Pilze und Bakterien nutzen abgestorbene Reste aller Gruppen. Von 1000 kJ als Pflanzenbiomasse verfügbarer Energie erscheinen im Modell 120 kJ als neue Herbivorenbiomasse und 12 kJ als neue Räuberbiomasse. Nach Zunahme der Heuschrecken nimmt die Froschzahl zeitversetzt zu.','Original meadow model: grass is eaten by grasshoppers and mice; frogs eat grasshoppers, storks eat frogs and mice. Fungi and bacteria use dead remains of every group. Of 1000 kJ available in plant biomass, the model has 120 kJ in new herbivore biomass and 12 kJ in new predator biomass. A grasshopper increase is followed by a delayed frog increase.'),
      pair('Stelle das Nahrungsnetz mit ausdrücklich definierter Pfeilrichtung dar. Beschreibe den Energiefluss, die Rolle der Destruenten und eine mögliche Populationsrückkopplung. Begrenze die Aussage der drei Energiewerte.','Represent the food web with an explicitly defined arrow convention. Describe energy flow, the role of decomposers and a possible population feedback. Limit what the three energy values establish.'),
      pair('Pfeile von Nahrung zu Verbraucher: Gras→Heuschrecke→Frosch→Storch und Gras→Maus→Storch; Reste aller Ebenen→Destruenten. Energie kommt letztlich von Licht, wird in Biomasse übertragen und durch Stoffwechsel als Wärme entwertet; sie kreist nicht mit Mineralstoffen zurück. Die gegebenen Übergänge betragen 12% und 10%, keine universelle Zehnprozentregel. Mehr Beute kann mehr Frösche ermöglichen, deren Fraß die Beute begrenzt; Konkurrenz, Wetter und weitere Netzbeziehungen können den Verlauf ändern. Zeitversatz allein beweist diesen Kausalweg nicht.','Arrows from food to consumer: grass→grasshopper→frog→stork and grass→mouse→stork; remains from all levels→decomposers. Energy ultimately enters as light, is transferred through biomass and dissipates as heat through metabolism; it does not cycle back with minerals. The given transfers are 12% and 10%, not a universal ten-percent rule. More prey may support more frogs, whose feeding can limit prey; competition, weather and other web links can change the course. A time lag alone does not establish this causal pathway.')),
 case(pair('Synthetisches Teichnetz: Algen→Wasserflöhe; Algen→Schnecken; Wasserflöhe→kleine Fische; kleine Fische und Schnecken→große Fische. Destruenten nutzen Reste. Ein Modellversuch vermindert große Fische; kleine Fische steigen, Wasserflöhe sinken, Algen steigen. Neue Biomasse pro betrachteter Zeit: Algen 600 kJ, Herbivoren 90 kJ, kleine Fische 9 kJ.','Synthetic pond web: algae→water fleas; algae→snails; water fleas→small fish; small fish and snails→large fish. Decomposers use remains. A model intervention reduces large fish; small fish increase, water fleas decrease and algae increase. New biomass during the specified interval: algae 600 kJ, herbivores 90 kJ, small fish 9 kJ.'),
      pair('Beschreibe Netz, Energiefluss und die indirekte Populationsfolge. Erkläre, warum eine Nahrungskette und diese Zahlen allein keine sichere Prognose für jeden echten Teich erlauben.','Describe the web, energy flow and the indirect population consequence. Explain why a chain and these values alone cannot predict every real pond.'),
      pair('Das Netz verzweigt bei Algen und großen Fischen. Weniger Fraß durch große Fische kann kleine Fische fördern; deren stärkerer Fraß begrenzt Wasserflöhe, dadurch sinkt Algenfraß. Diese trophische Kaskade ist eine bedingte Modellhypothese. Energieübergänge sind 15% und 10%; Nahrung, Stoffwechsel und nicht aufgenommene Reste erklären Energieverteilung, Wärme wird nicht zur nächsten Produzentenenergie recycelt. Reale Nahrungsauswahl, Schnecken, Nährstoffzufuhr und andere Faktoren können Vorzeichen und Stärke verändern.','The web branches at algae and large fish. Reduced predation by large fish may favour small fish; their increased feeding limits water fleas and therefore reduces grazing on algae. This trophic cascade is a conditional model hypothesis. Transfers are 15% and 10%; feeding, metabolism and unconsumed remains account for energy distribution, and heat is not recycled into the next producer energy input. Real diets, snails, nutrient input and other factors can alter the direction and magnitude.'))
],
[
 case(pair('Eigenes Blattmodell bei gleicher Blattmasse: Pflanze A hat ein schmales gerolltes Blatt mit dicker Cuticula und geschützten Spaltöffnungen; B eine breite dünnere Blattspreite. A wächst im trockenen windigen Standort, B bei verlässlicher Wasserzufuhr und geringerer Beleuchtung. Keine dieser Pflanzen wurde in diesem Paket real untersucht.','Original leaf model at equal leaf mass: plant A has a narrow rolled leaf with a thick cuticle and sheltered stomata; B has a broad thinner blade. A grows at a dry windy site, B with reliable water supply and lower light. Neither plant was actually investigated in this package.'),
      pair('Erläutere die strukturellen Angepasstheiten beider Pflanzen an Wasser- und Lichtbedingungen und einen Zielkonflikt. Trenne Bau, mögliche Funktion und nicht belegte Verallgemeinerung.','Explain both plants\' structural adaptations to water and light and one trade-off. Separate structure, possible function and unsupported generalization.'),
      pair('A verringert durch geringere exponierte Fläche, Cuticula und geschützte Spaltöffnungen den Wasserverlust; die Kombination kann jedoch Gasaustausch und Lichtaufnahme begrenzen. Bs größere Fläche erschließt bei schwächerem Licht mehr Strahlung, kann aber Wasserverlust erhöhen. Struktur-Funktions-Erklärungen sind artspezifisch; nicht jede Trockenpflanze besitzt alle Merkmale, und das Material belegt keine spontane willentliche Umbildung eines Blatts.','A can reduce water loss through less exposed area, cuticle and sheltered stomata, but the combination may restrict gas exchange and light capture. B\'s larger area can intercept more radiation under low light but may increase water loss. Structure-function explanations are species specific; not every dry-site plant has every trait, and the material provides no evidence of deliberate instant remodelling of a leaf.')),
 case(pair('Synthetischer Standortvergleich: Flachgründiger Boden wird nach kurzen Regengüssen nur oberflächlich nass; Standort C ist dauerhaft überschwemmt und sauerstoffarm. Modellpflanze D hat oberflächennahe weit verzweigte Wurzeln und wasserspeicherndes Gewebe; Modellpflanze E besitzt luftgefüllte Geweberäume bis zu über Wasser stehenden Blättern.','Synthetic site comparison: shallow soil becomes wet near the surface after brief rain; site C is continuously flooded and oxygen poor. Model plant D has shallow spreading roots and water-storing tissue; model plant E has air-filled tissue spaces extending to leaves above water.'),
      pair('Ordne D und E begründet zu und erläutere die Funktion jedes genannten Bauaspekts. Diskutiere, weshalb dieselbe Struktur bei veränderten Umweltbedingungen nachteilig sein kann.','Assign D and E with reasons and explain every listed structural feature. Discuss why the same structure can be disadvantageous under changed conditions.'),
      pair('D passt zum episodisch oberflächlich befeuchteten Standort: weit verteilte flache Wurzeln erschließen kurze Wasserpulse; Speichergewebe überbrückt Trockenzeiten. E passt zum überschwemmten Standort: Luftgewebe erleichtert inneren Gastransport und Sauerstoffversorgung trotz sauerstoffarmen Bodens. Flache Wurzeln sind bei tieferem dauerhaftem Wasser ungünstiger; Speicher- und Luftgewebe kosten Aufbauressourcen. Dies sind funktionale Modellzuordnungen, keine automatische sichere Artbestimmung oder Überlebensgarantie.','D fits the intermittently surface-wet site: spreading shallow roots access short water pulses, and storage tissue bridges dry periods. E fits the flooded site: air spaces facilitate internal gas transport and oxygen supply despite oxygen-poor soil. Shallow roots can be less suitable when reliable water is deeper; storage and air tissues require resources. These are functional model assignments, not certain species identification or survival guarantees.'))
],
[
 case(pair('Zwei endotherme Modellsäugetiere: A ist kompakt, besitzt kleine exponierte Ohren und dichtes Fell; B besitzt größere dünne Ohren. Bei B kann die Durchblutung der Ohren variieren. In kalter Umgebung erhöht A die Stoffwechselwärme.','Two endothermic model mammals: A is compact with small exposed ears and dense fur; B has larger thin ears. B can vary blood flow through its ears. In cold conditions A increases metabolic heat production.'),
      pair('Beschreibe morphologische und physiologische Angepasstheiten getrennt und verknüpfe sie mit Umweltfaktoren. Nenne eine Grenze der einfachen Form-Wärme-Deutung.','Describe morphological and physiological adaptations separately and link them to environmental factors. Give a limitation of the simple shape-heat interpretation.'),
      pair('Kompakter Körper, kleinere exponierte Ohren und Fell beeinflussen den Wärmeübergang als morphologische Merkmale. Stoffwechselwärme und veränderliche Ohrdurchblutung sind physiologische Regulation; erhöhte Hautdurchblutung kann Wärmeabgabe fördern, verringerte sie begrenzen. Größere Ohren können bei Wärme nützen, kosten bei Kälte aber Schutz. Klima allein erklärt nicht jede Körperform; Verhalten, Körpergröße, Abstammung und verfügbare Energie wirken mit.','Compact shape, smaller exposed ears and fur influence heat transfer as morphological traits. Metabolic heat and variable ear circulation are physiological regulation; increased skin blood flow can promote heat loss, reduced flow can restrict it. Larger ears may help in warmth but require protection in cold. Climate alone does not explain every body shape; behaviour, body size, ancestry and energy supply also matter.')),
 case(pair('Synthetische Wasserhaushaltsmodelle: Tier C besitzt eine relativ wasserundurchlässige Körperbedeckung und kann stark konzentrierten Harn bilden; Tier D lebt in Süßwasser, nimmt osmotisch Wasser auf und scheidet viel verdünnten Harn aus. Das Material beschreibt Modellfunktionen, keine reale Messung.','Synthetic water-balance models: animal C has a relatively water-resistant covering and can produce concentrated urine; D lives in fresh water, gains water osmotically and excretes much dilute urine. These are model functions, not real measurements.'),
      pair('Beschreibe je eine morphologische und physiologische Eigenschaft, begründe ihren Zusammenhang mit dem Habitat und erkläre, warum D nicht unverändert für eine trockene Umgebung geeignet wäre.','Describe a morphological and physiological property, justify their habitat relationships and explain why D would not be unchangedly suitable for dry conditions.'),
      pair('Cs Körperbedeckung begrenzt Verdunstung morphologisch; Harnkonzentrierung spart Wasser physiologisch. D gleicht osmotische Wasseraufnahme durch verdünnte Harnabgabe aus; aus dem Fall folgt kein besonderer trockentauglicher Körperbau. Dauernd viel Wasser auszuscheiden wäre ohne entsprechende Wasserzufuhr nachteilig. Angepasstheit umfasst Bau und Regulation unter bestimmten Bedingungen, keine allgemeine Höherentwicklung oder bewusste Zielsetzung.','C\'s covering limits evaporation morphologically, while urine concentration conserves water physiologically. D offsets osmotic water gain through dilute urine excretion; the case establishes no special dry-adapted body shape. Continually excreting much water would be disadvantageous without matching input. Adaptation includes structure and regulation under particular conditions, not general advancement or deliberate purpose.'))
],
[
 case(pair('Eigenes dimensionsloses Modell: Beutebestand N, Räuberbestand P. dN/dt = aN − bNP, dP/dt = cNP − dP; a,b,c,d sind positive konstante Modellparameter. Keine Einwanderung, kein zweites Beutefutter; Beute hat ohne Räuber unbegrenzte Modellressourcen. Ein schematischer Verlauf zeigt Beutegipfel vor Räubergipfel.','Original dimensionless model: prey N, predators P. dN/dt = aN − bNP, dP/dt = cNP − dP; a,b,c,d are positive constant model parameters. No immigration or alternative prey; without predators the prey has unlimited model resources. A schematic course shows a prey peak before the predator peak.'),
      pair('Erläutere die Bedeutung aller vier Terme, die Zeitverschiebung und eine Modellgrenze. Bestimme die positiven Gleichgewichtsbestände aus dem Modell, ohne daraus reale konstante Bestände zu behaupten.','Explain all four terms, the time lag and a model limitation. Derive the positive equilibrium abundances without claiming that real populations remain constant.'),
      pair('aN ist Beutezunahme, bNP Beuteverlust durch Begegnung/Fraß, cNP Räuberzunahme aus Beuteangebot, dP Räuberverlust. Mehr Beute fördert erst nachfolgend Räuberzunahme; hoher Räuberdruck begrenzt Beute und später mangelt Räubern Nahrung. Positives Gleichgewicht: P=a/b und N=d/c. Das Gleichgewicht bedeutet Änderungsraten null unter den Annahmen, nicht garantierte reale Ruhe. Endliche Ressourcen, Wetter, alternative Nahrung und Migration fehlen.','aN is prey growth, bNP prey loss through encounters/feeding, cNP predator growth from prey availability and dP predator loss. More prey subsequently promotes predators; high predator pressure limits prey and later food becomes scarce for predators. Positive equilibrium: P=a/b and N=d/c. Equilibrium means zero rates of change under the assumptions, not guaranteed real stability. Finite resources, weather, alternative food and migration are omitted.')),
 case(pair('Neues synthetisches Wachstumsmodell ohne Räuber: dN/dt = rN(1−N/K), r=0,4 pro Modellzeit, K=100 Individuen. Zustände A:N=20, B:N=80, C:N=120. Eine Nahrungsknappheit senkt K später auf 50.','New synthetic growth model without predators: dN/dt = rN(1−N/K), r=0.4 per model time, K=100 individuals. States A:N=20, B:N=80, C:N=120. Later food scarcity lowers K to 50.'),
      pair('Nutze das dynamische Modell, berechne die anfänglichen Änderungsraten und erkläre die Kapazitätsänderung. Vergleiche seine Rückkopplung mit dem Räuber-Beute-Modell und begrenze die Vorhersage.','Use the dynamic model to calculate initial rates and explain the capacity change. Compare its feedback with the predator-prey model and limit the prediction.'),
      pair('A und B wachsen jeweils mit 6,4 Individuen pro Modellzeit; C nimmt mit −9,6 ab. Selbstbegrenzung wirkt über N/K, nicht über den expliziten Räuberterm. Bei K=50 liegt N=80 oberhalb der Kapazität und die Rate wird −19,2. K ist ein bedingter Modellparameter, kein unveränderlicher Naturwert; das deterministische Modell bildet keine Zufallsschwankung, Altersstruktur oder Anpassung ab.','A and B each grow at 6.4 individuals per model time; C decreases at −9.6. Self-limitation operates through N/K rather than an explicit predator term. At K=50, N=80 exceeds capacity and the rate becomes −19.2. K is a conditional model parameter, not a fixed natural constant; the deterministic model omits random fluctuations, age structure and adaptation.'))
],
[
 case(pair('Synthetischer Ufervergleich: Alternative A ersetzt Schilf und flache Buchten durch eine durchgehende Mauer; B erhält 80% naturnahes Ufer und richtet einen kleinen sicheren Zugang ein. Laichplätze und Verstecke liegen überwiegend im Schilf. Ein allgemeiner Artenzuwachs wurde nicht gemessen.','Synthetic bank comparison: option A replaces reeds and shallow bays with a continuous wall; B retains 80% natural bank and creates one small safe access. Spawning and refuge sites mainly occur in reeds. No general species increase has been measured.'),
      pair('Beurteile beide Maßnahmen zur Stabilisierung der Gemeinschaft anhand von Wirkmechanismen, Nutzung und Unsicherheit. Plane eine geeignete Erfolgskontrolle statt einen Erfolg vorauszusetzen.','Assess both measures for stabilizing the community using mechanisms, use and uncertainty. Plan suitable monitoring instead of presuming success.'),
      pair('A beseitigt Fortpflanzungs- und Rückzugsstrukturen mehrerer Gruppen; B erhält diese Funktionen großteils und ermöglicht begrenzte Erholung. B ist im beschriebenen Rahmen plausibler, aber Wassergüte, Störung und Zugangssicherheit bleiben zu prüfen. Wiederholte standardisierte Aufnahmen von Uferstruktur und ausgewählten Organismengruppen vor/nach der Maßnahme, möglichst mit Vergleichsufer, prüfen Änderungen. Einzelne mehr gezählte Arten beweisen ohne vergleichbare Erhebung keine Wirkung.','A removes reproduction and refuge structures for several groups; B largely retains them while allowing limited recreation. B is more plausible within this case, but water quality, disturbance and access safety still need assessment. Repeated standardized surveys of bank structure and selected organism groups before and after the intervention, preferably with a comparison bank, assess changes. A one-off increase in counts does not establish an effect without comparable sampling.')),
 case(pair('Modellwald: Regelmäßige großflächige Entnahme aller Altbäume/Totholzstrukturen versus kleine gestaffelte Nutzung mit erhaltenen Altbauminseln und Verbindungen. Totholzorganismen benötigen kontinuierlich geeignete Substrate, Besucherwege haben konkrete Sicherheitsansprüche.','Model woodland: repeated large-scale removal of all old trees/dead wood versus small staggered harvest with retained old-tree patches and connections. Dead-wood organisms need continuously suitable substrates; visitor paths have specific safety needs.'),
      pair('Bewerte die Alternativen als Gemeinschaftsmanagement, erläutere einen Zielkonflikt und leite begründete Schutz- sowie Kontrollmaßnahmen ab.','Evaluate the alternatives as community management, explain a trade-off and derive justified conservation and monitoring measures.'),
      pair('Gestaffelte Nutzung und verbundene Altbauminseln erhalten eher Habitatkontinuität und Ausbreitung; vollständige Entnahme unterbricht Ressourcen. Sicherheit erfordert gezielte Behandlung tatsächlicher Gefahren an Wegen, nicht pauschales Ausräumen des Waldes. Wirtschaftliche Erträge, Schutz und Zugang sind zu gewichten. Kontrolliert werden Habitatmenge/-verteilung und vergleichbare wiederholte Nachweise ausgewählter Gruppen. Welche Option stabilisiert, hängt vom Ziel, Maßstab und tatsächlichen Befunden ab.','Staggered harvest and connected old-tree patches better retain habitat continuity and dispersal; complete removal interrupts resources. Safety calls for targeted treatment of actual path hazards, not blanket clearing of woodland. Income, protection and access require weighting. Monitoring addresses habitat amount/distribution and comparable repeated records of selected groups. Stabilization depends on objectives, scale and actual findings.'))
],
[
 case(pair('Synthetische physiologische Zeitreihen: Kleinsäuger A senkt Körpertemperatur von 37°C auf 18°C und Sauerstoffverbrauch von Modellindex100 auf20 während sechs Stunden pro Nacht; tagsüber kehren beide Werte zurück. B verbringt mehrere Winterwochen mit wiederholten längeren Phasen auf 6°C und Index5, unterbrochen von kurzen Erwärmungen.','Synthetic physiological time series: small mammal A lowers body temperature from 37°C to 18°C and oxygen consumption from model index100 to20 during six hours each night; both recover during daytime. B spends several winter weeks in repeated longer phases at 6°C and index5, interrupted by brief warming episodes.'),
      pair('Erkläre A als täglichen Torpor und B als Winterschlaf, gemeinsame Energieersparnis und Unterschiede. Begrenze, was die Modellwerte über echte Arten zeigen.','Explain A as daily torpor and B as hibernation, their shared energy saving and differences. Limit what the model values establish for real species.'),
      pair('Beide regulieren Stoffwechsel und Körpertemperatur abwärts und sparen dadurch Energie bei begrenztem Nahrungsangebot. A ist kurzfristig täglich, B länger saisonal mit Aufwachphasen; Winterschlaf ist nicht einfach ununterbrochener gewöhnlicher Schlaf. Erwärmung kostet Energie, Überleben braucht Reserven und sichere Bedingungen. Die Werte sind synthetisch, artabhängig und keine Universaltemperaturen; Sauerstoffverbrauchsindex ist nur ein vereinfachter Stoffwechselindikator.','Both lower metabolism and body temperature through regulation, saving energy when food is limited. A is short daily torpor; B is longer seasonal hibernation with arousals, not uninterrupted ordinary sleep. Rewarming costs energy, and survival needs reserves and suitable conditions. Values are synthetic and species dependent, not universal temperatures; the oxygen index is a simplified metabolic indicator.')),
 case(pair('Eigenes Wintermodell: Tier C bleibt in langen kalten Wochen endotherm nahe 37°C und verbraucht gespeichertes Futter. Tier D wechselt zwischen mehrtägiger starker Absenkung von Temperatur/Stoffwechsel und kurzen Erwärmungen; in einer warmen Woche erwacht D häufiger. Ein kleines Tier E nutzt nur kurze morgendliche Absenkungen.','Original winter model: C stays endothermic near 37°C through long cold weeks and uses stored food. D alternates multi-day marked temperature/metabolic depression and short warming episodes; it arouses more often in a warm week. Small animal E only uses brief morning depressions.'),
      pair('Vergleiche C, D und E und erkläre, warum Torpor/Winterschlaf als Anpassungen nützen können, aber häufigere Erwärmungen auch Reserven aufbrauchen. Trenne Modellbegründung und reale Erfolgsaussage.','Compare C, D and E and explain why torpor/hibernation can be useful adaptations while more frequent rewarming can consume reserves. Separate model explanation from real success claims.'),
      pair('C zeigt nach den Angaben keinen Torpor; D saisonalen Winterschlaf mit einzelnen Torporphasen und E kurzen täglichen Torpor. Absenkung reduziert laufenden Energiebedarf, Wiedererwärmung ist kostspielig. Häufigere Aufwachphasen können den Vorteil verringern, ohne dass diese Angaben einen exakten Gesamtenergieverlust bestimmen. Dauer, Ausmaß, Nahrungsverfügbarkeit und artspezifische Regulation wirken zusammen; warme Bedingungen sind nicht automatisch immer besser.','C shows no torpor in the material; D shows seasonal hibernation with individual torpor bouts and E brief daily torpor. Depression reduces continuing energy demand, while rewarming is costly. More frequent arousals may reduce the benefit, but the information does not determine exact total energy loss. Duration, depth, food availability and species-specific regulation interact; warmth is not automatically always better.'))
],
[
 case(pair('Synthetischer ökologischer Fußabdruck in globalen Hektar pro Person: Ernährung1,4, Mobilität1,0, Wohnen1,2, übriger Konsum0,8. Verfügbare Biokapazität im Modell1,8 gha/Person. Maßnahme X verringert Mobilität um0,4 und Ernährung um0,3, erhöht aber sonstigen Konsum um0,1.','Synthetic ecological footprint in global hectares per person: food1.4, mobility1.0, housing1.2, other consumption0.8. Available model biocapacity1.8 gha/person. Measure X reduces mobility by0.4 and food by0.3 but increases other consumption by0.1.'),
      pair('Analysiere Ausgangszustand und Maßnahme für nachhaltige Entwicklung. Berechne die Summen und Biokapazitätsrelation und benenne ökologische sowie soziale Grenzen dieses Indikators.','Analyze the baseline and measure for sustainable development. Calculate totals and the biocapacity relation and identify ecological and social limitations of the indicator.'),
      pair('Ausgang4,4 gha, nach X3,8 gha; Nettoverminderung0,6 gha. Modellrelationen4,4/1,8≈2,44 und3,8/1,8≈2,11: Entlastung, aber weiterhin über der modellierten Biokapazität. Dies vergleicht Flächenäquivalente für Ressourcen-/Aufnahmeanforderungen, nicht nur CO2 oder eine exakte persönliche Schuld. Biodiversität, lokale Wasserknappheit, Verteilungsgerechtigkeit und andere Nachhaltigkeitsdimensionen werden nicht vollständig erfasst; Werte beruhen auf Annahmen.','Baseline4.4 gha, after X3.8 gha; net reduction0.6 gha. Model ratios4.4/1.8≈2.44 and3.8/1.8≈2.11 show relief but continued demand above model biocapacity. This compares equivalent areas for resource/absorption demand, not only CO2 or exact personal blame. Biodiversity, local water scarcity, distributive justice and other sustainability dimensions are not fully captured; values depend on assumptions.')),
 case(pair('Neues Gemeindemodell: mittlerer Fußabdruck fällt von3,6 auf3,0 gha/Person, Einwohnerzahl steigt von10000 auf13000. Biokapazität beträgt in beiden Zeitpunkten20000 gha. Maßnahme Y schützt zusätzlich einen seltenen Lebensraum, der im Fußabdruck kaum abgebildet ist.','New municipality model: mean footprint falls from3.6 to3.0 gha/person, population rises from10000 to13000. Biocapacity is20000 gha at both times. Measure Y additionally protects a rare habitat barely represented by the footprint.'),
      pair('Vergleiche persönliche und gesamte Belastung. Beurteile, warum ein kleinerer Mittelwert allein keine vollständige Nachhaltigkeitsverbesserung beweist und Y dennoch ökologisch sinnvoll sein kann.','Compare personal and aggregate pressure. Assess why a smaller mean alone does not establish a complete sustainability improvement and Y can still have ecological value.'),
      pair('Gesamtbedarf steigt von36000 auf39000 gha; Relation zur Biokapazität1,8→1,95. Pro-Kopf-Entlastung und größere Gesamtbelastung können zugleich gelten. Nachhaltigkeit braucht daher Maßstab, Bevölkerungsentwicklung, Rechte/Verteilung und zusätzliche Indikatoren. Habitatqualität und nicht ersetzbare Artenwerte können Y rechtfertigen, auch wenn die Flächensumme kaum reagiert. Das Modell beschreibt keine tatsächliche Gemeinde oder vollständige Ökobilanz.','Aggregate demand rises from36000 to39000 gha; the biocapacity ratio changes1.8→1.95. Per-capita relief can coincide with greater aggregate pressure. Sustainability therefore needs scale, population development, rights/distribution and additional indicators. Habitat quality and irreplaceable species values can justify Y even when the area sum barely changes. This model represents neither an actual municipality nor a complete life-cycle assessment.'))
],
[
 case(pair('Noch durchzuführende erlaubte schulische Felduntersuchung: Wähle ein sicher zugängliches Wiesenareal; lege drei vergleichbar große Quadrate mit nachvollziehbarer Auswahl fest. Nutze Bestimmungshilfe, Thermometer und einfache Feuchtebeobachtung. Nur beobachten, keine geschützten Organismen entnehmen. Es liegen noch keine tatsächlichen Rohdaten vor.','School field investigation still to be performed with permission: choose a safely accessible meadow; establish three equal-sized quadrats with traceable selection. Use an identification key, thermometer and simple moisture observation. Observe only; do not collect protected organisms. No actual raw data yet exist.'),
      pair('Führe die Untersuchung tatsächlich durch. Protokolliere Ort, Datum, Flächen, Methoden, eigene Temperatur-/Feuchtebefunde und qualitativ belegte Pflanzengruppen. Werte Unterschiede aus und trenne Beobachtung, Hypothese und Stichprobengrenze.','Actually conduct the investigation. Record site, date, areas, methods, personal temperature/moisture findings and qualitatively supported plant groups. Analyze differences and separate observation, hypothesis and sampling limitations.'),
      pair('Vollständiger späterer Nachweis umfasst eigenes nachvollziehbares Feldprotokoll mit tatsächlich erhobenen Rohbefunden und einer begründeten Auswertung. Vergleichbare Fläche, Zeit und Verfahren begrenzen Störfaktoren; unsichere Bestimmungen bleiben gruppenscharf/unsicher. Abiotische Befunde und beobachtete lebende Gemeinschaft werden getrennt. Aus drei Quadraten folgen weder alle Arten des Ökosystems noch ein Kausalbeweis. Ohne Durchführung und eigene Daten ist nur Planung vorhanden; Zahlen und standortspezifisches Ergebnis bleiben offen.','Complete later evidence includes a traceable personal field record with actually collected raw findings and justified analysis. Comparable area, time and methods limit confounding; uncertain identifications stay at supported group/uncertainty level. Abiotic observations and the observed living community are separated. Three quadrats establish neither every ecosystem species nor causation. Without performance and personal data this is planning only; numbers and site-specific results remain open.'),
      pair('Echte feldbiologische Durchführung ist zwingend. Dieses E1/G1-Autormaterial enthält keine erfundenen Ist-Werte und behauptet keine abgeschlossene Leistung.','Actual field performance is mandatory. This E1/G1 author material supplies no invented actual values and claims no completed performance.')),
 case(pair('Zweite reale Untersuchungsaufgabe: Vergleiche zwei sicher zugängliche Uferabschnitte eines Gewässers mit gleichem Beobachtungszeitfenster. Unter Aufsicht nutze Thermometer und einen passenden schulischen Wasserqualitätsindikator. Erfasse beobachtete Pflanzen-/Tiergruppen schonend mit Hilfen; keine Freisetzung, kein gefährlicher Wassereinstieg.','Second actual investigation task: compare two safely accessible banks with the same observation window. Under supervision use a thermometer and an appropriate school water-quality indicator. Carefully survey observed plant/animal groups with identification aids; no releases or hazardous entry into water.'),
      pair('Untersuche beide Abschnitte tatsächlich und lege eigene Rohbefunde, Methoden/Einheiten, Suchaufwand und Unsicherheiten vor. Werte Gemeinsamkeiten und Unterschiede im Zusammenhang mit dem Habitat aus. Erfinde keine nicht beobachteten Arten oder Konzentrationen.','Actually investigate both banks and present personal raw findings, methods/units, search effort and uncertainties. Analyze similarities and differences in relation to habitat. Invent neither unobserved species nor concentrations.'),
      pair('Erwartet sind tatsächliche vergleichbare Erhebungen, eigenes Protokoll und eigenständige Auswertung. Unterschiedlicher Suchaufwand wird vermieden oder offengelegt; Temperaturskala/Qualitätsindikator und Beobachtungsmethoden sind passend. Weniger Nachweise können Detektionsunterschiede statt geringerer Gesamtvielfalt bedeuten. Standortzusammenhänge werden als begrenzte Deutungen, nicht als bewiesene Einzelursachen behandelt. Ohne Durchführung gibt es keinen vollen Leistungsnachweis; Modelltabellen können Auswertung üben, ersetzen diesen Auftrag aber nicht.','Expected evidence consists of actual comparable surveys, a personal record and independent analysis. Different search effort is avoided or disclosed; temperature scale/quality indicator and observation methods are appropriate. Fewer records may reflect detection differences rather than lower total diversity. Site relationships are bounded interpretations, not proven single causes. Without performance there is no complete performance evidence; model tables can practise analysis but cannot replace this task.'),
      pair('Durchführung und eigene Befunde bleiben verpflichtend; keine vorgetäuschte reale Datenerhebung, kein E2-/menschlicher Prüfungsnachweis.','Performance and personal findings remain required; no fabricated real survey, E2 evidence or human assessment.'))
],
[
 case(pair('Eigene synthetische Konzentrationen eines persistenten lipophilen Stoffes, jeweils mg/kg Gewebe derselben Bezugsart: bei einem Fisch über Wochen0,2→0,5→0,9; im gleichzeitig aufgenommenen Netz Wasserorganismen0,1, kleine Fische0,8, Raubfische3,2. Es gibt keinen Messnachweis einer Schädigung.','Original synthetic concentrations of a persistent lipophilic substance, all in mg/kg tissue on the same basis: one fish over weeks0.2→0.5→0.9; in the simultaneously sampled web aquatic organisms0.1, small fish0.8, predatory fish3.2. No measured injury evidence is supplied.'),
      pair('Analysiere Bioakkumulation und Biomagnifikation getrennt, berechne einen Konzentrationsfaktor und erläutere eine mögliche Ökosystemfolge samt Beweisgrenze.','Analyze bioaccumulation and biomagnification separately, calculate one concentration factor and explain a possible ecosystem effect with its evidential limit.'),
      pair('Der zeitliche Anstieg im einzelnen Fisch zeigt Modell-Bioakkumulation; die Konzentrationszunahme zwischen Trophiegruppen zeigt Modell-Biomagnifikation. Raubfisch/kleiner Fisch=4. Persistenz, Aufnahme und geringe Ausscheidung können dies erklären. Eine toxische Beeinträchtigung von Fortpflanzung oder Überleben könnte Nahrungsbeziehungen verändern, ist aus den Konzentrationen allein aber nicht nachgewiesen; Dosis-Wirkung, Stoffeigenschaften, Gewebebasis und Exposition sind zu prüfen. Nicht jeder Schadstoff biomagnifiziert.','The temporal increase within one fish is model bioaccumulation; the concentration increase across trophic groups is model biomagnification. Predator/small fish=4. Persistence, uptake and limited elimination can explain this. Toxic effects on reproduction or survival could alter food relationships, but concentrations alone do not establish injury; dose-response, chemical properties, tissue basis and exposure must be assessed. Not every pollutant biomagnifies.')),
 case(pair('Neues synthetisches Netz, vergleichbar gemessene Gewebekonzentrationen mg/kg: Produzenten2, Herbivoren1, Räuber0,4. Eine einzelne langlebige Muschel steigt über Monate von0,2 auf1,0. Der Stoff wird bei Räubern rasch ausgeschieden; ein Begleitstoff kann hormonartig wirken, ohne dass zu seiner Wirkung Daten vorliegen.','New synthetic web, comparable tissue concentrations in mg/kg: producers2, herbivores1, predators0.4. One long-lived mussel rises from0.2 to1.0 over months. Predators rapidly eliminate the substance; a co-occurring chemical may act hormonally but no effect data are provided.'),
      pair('Prüfe beide Anreicherungsbegriffe und korrigiere die Behauptung „jeder Stoff wird nach oben giftiger“. Leite eine sinnvolle Untersuchung möglicher Ökosystemwirkungen ab.','Test both accumulation concepts and correct the claim that every substance becomes more toxic higher in the web. Derive a useful study of possible ecosystem effects.'),
      pair('Die Muschel zeigt zeitliche Bioakkumulation; die fallenden Trophiekonzentrationen belegen hier gerade keine Biomagnifikation. Konzentration und Giftigkeit sind unterschiedliche Begriffe; Ausscheidung und Stoffabbau beeinflussen Muster. Für den hormonartigen Begleitstoff braucht man geeignete Expositions-/Wirkungsdaten mit Kontrollen, etwa zu Fortpflanzung, und nicht bloß die Nahrungsebenen. Reale Gemeinschaftsfolgen erfordern verknüpfte Befunde und andere Ursachenprüfung.','The mussel shows temporal bioaccumulation; decreasing trophic concentrations specifically show no biomagnification here. Concentration and toxicity are distinct; elimination and degradation influence patterns. The hormonally active co-occurring substance requires suitable exposure/effect data with controls, for example on reproduction, not merely trophic levels. Real community consequences need connected evidence and assessment of other causes.'))
],
[
 case(pair('Eigenes stochastisches Patchmodell: vier geeignete voneinander getrennte Habitate, zu Beginn zwei bewohnt. In einem Zeitschritt stirbt jede bewohnte Teilpopulation mit Wahrscheinlichkeit e=0,25 aus; jeder anfangs leere Patch wird mit Wahrscheinlichkeit c=0,5 kolonisiert. Übergänge beziehen sich auf den Anfangszustand; kein Patch erhält im gleichen Schritt zwei Änderungen. Gegebene Zufallszahlen: bewohnte Patches0,10 und0,70; leere Patches0,20 und0,80. Ereignis tritt bei Zahl<p ein.','Original stochastic patch model: four suitable separated habitats, initially two occupied. During one step each occupied population becomes extinct with probability e=0.25; each initially empty patch is colonized with probability c=0.5. Transitions refer to the initial state; no patch changes twice in the same step. Given random numbers: occupied patches0.10 and0.70; empty patches0.20 and0.80. An event occurs when the number<p.'),
      pair('Nutze die Regeln, ermittle diesen Modellschritt und die erwartete Belegungszahl. Erläutere, weshalb beides nicht dasselbe wie eine garantierte reale Zukunft ist.','Use the rules to determine this step and the expected occupancy count. Explain why neither is a guaranteed real future.'),
      pair('Ein bewohnter Patch stirbt aus, einer bleibt; ein leerer wird kolonisiert, einer bleibt leer: realisierter Modellstand2. Erwartete Zahl=2×0,75+2×0,5=2,5; eine Erwartung darf nicht ganzzahlig sein, einzelne Realisationen sind ganzzahlig. Andere Zufallszahlen liefern andere Verläufe. Unabhängige konstante Übergangschancen und gleich geeignete Habitate sind Vereinfachungen; tatsächliche Vernetzung, Umweltschwankung und Abhängigkeiten fehlen.','One occupied patch becomes extinct and one stays occupied; one empty patch is colonized and one remains empty: realized model count2. Expected count=2×0.75+2×0.5=2.5; an expectation need not be an integer, while individual realizations are integers. Other random numbers yield other paths. Independent constant transition probabilities and equally suitable habitats are simplifications; actual connectivity, environmental variation and dependencies are omitted.')),
 case(pair('Neues synthetisches Ein-Schritt-Modell mit sechs Patches, anfangs vier bewohnt. Ohne Verbindung c=0,1 und e=0,25; mit Habitatkorridor c=0,6 und unverändert e=0,25. Kolonisation/Aussterben werden wie in Fall1 aus dem Anfangszustand bestimmt. Wetterereignisse können in Wirklichkeit mehrere Patches zugleich treffen.','New synthetic one-step model with six patches, initially four occupied. Without connection c=0.1 and e=0.25; with a corridor c=0.6 and unchanged e=0.25. Colonization/extinction are determined from the initial state as in case1. Real weather events can affect several patches simultaneously.'),
      pair('Berechne erwartete nächste Belegungen, bewerte die Verbindung im Modell und erläutere eine Grenze der unabhängigen Zufallsannahmen. Nenne eine Prüfung mit mehreren Realisationen.','Calculate expected next occupancies, assess connectivity in the model and explain a limitation of independent random assumptions. Name a check using multiple realizations.'),
      pair('Ohne Verbindung4×0,75+2×0,1=3,2; mit Verbindung3+1,2=4,2. Modellgewinn1 erwarteter Patch, kein sicherer individueller Erfolg. Wiederholte simulierte Realisationen mit dokumentierten Zufallsfolgen zeigen Streuung und den Anteil vollständigen Aussterbens. Gemeinsames Wetter erzeugt korrelierte Risiken; ein Korridor kann zudem Krankheiten/Prädatoren verbreiten. Reale c/e brauchen geeignete Daten, das Modell behauptet keine tatsächlich erfolgte Wiederbesiedlung.','Without connection4×0.75+2×0.1=3.2; with connection3+1.2=4.2. The model gain is one expected patch, not guaranteed individual success. Repeated simulated realizations with documented random sequences show variation and the proportion of total extinction. Shared weather creates correlated risk; corridors can also spread pathogens/predators. Real c/e require suitable data, and the model claims no actual recolonization.'))
],
]

CASES += [
[
 case(pair('Eigene Lebenszyklusmodelle: Art A reift früh, erzeugt im Jahr200 kleine Nachkommen und betreibt wenig Elternpflege; Art B reift später, erzeugt4 Nachkommen und investiert viel in Pflege. Gebiet X wird häufig unvorhersehbar gestört und bietet danach viele freie Ressourcen; Gebiet Y ist länger stabil, dicht besiedelt und konkurrenzreich.','Original life-cycle models: A matures early, produces200 small offspring yearly and provides little care; B matures later, produces4 offspring and invests heavily in care. X is repeatedly unpredictably disturbed and then provides unused resources; Y stays stable longer and is densely populated with strong competition.'),
      pair('Bewerte beide Lebenszyklen im Umweltkontext anhand der idealisierten r-/K-Strategien. Erläutere einen Zielkonflikt und warum das Modell keine starre vollständige Einteilung aller Arten erlaubt.','Evaluate both life cycles in their environment using idealized r/K strategies. Explain a trade-off and why this does not produce rigid exhaustive classes for all species.'),
      pair('A entspricht eher schnellem Zuwachs/hoher Nachkommenzahl und kann freie kurzlebige Habitate rasch besiedeln; B investiert eher in Einzelüberleben und Konkurrenzfähigkeit unter länger stabilen Bedingungen. Mehr Nachkommen steht begrenzter Einzelinvestition gegenüber. r/K sind vereinfachte Endpunkte eines Merkmalskontinuums; Überlappung, Umweltänderung, Altersstruktur und konkrete Überlebensraten verhindern eine sichere binäre Erfolgsvorhersage.','A is closer to rapid increase/high offspring number and may quickly colonize short-lived free habitats; B invests more in individual survival and competitive performance under longer stable conditions. More offspring trades off against individual investment. r/K are simplified endpoints of a trait continuum; overlap, environmental changes, age structure and actual survival rates preclude certain binary success predictions.')),
 case(pair('Neues synthetisches Beispiel: Population C bringt viele Samen hervor, von denen in einem ungestörten konkurrenzreichen Bestand1% keimen und überleben, auf neuen offenen Flächen20%. D produziert weniger größere Samen; im dichten Bestand überleben20%, auf wiederholt überfluteten offenen Flächen2%. Die Unterschiede gelten nur im vorgegebenen Modell.','New synthetic example: C produces many seeds;1% germinate and survive in undisturbed crowded vegetation and20% on new open land. D produces fewer larger seeds;20% survive in crowded vegetation and2% on repeatedly flooded open land. Differences apply only to the supplied model.'),
      pair('Bewerte Lebenszyklusmerkmale und Standortabhängigkeit mit der r/K-Heuristik. Erkläre, weshalb eine Strategie nicht allgemein besser ist und welche zusätzlichen Daten Gesamtfitness beurteilen würden.','Evaluate life-cycle traits and site dependence with the r/K heuristic. Explain why one strategy is not generally superior and what data would establish total fitness.'),
      pair('C ähnelt hoher Ausbreitungs-/Reproduktionsleistung und profitiert im Modell von freien Flächen; D zeigt stärkere Einzelinvestition und Konkurrenzleistung im Bestand. Die wechselnden Überlebensraten kehren Vorteile um. Gesamtfitness braucht Nachkommenzahl, Überleben bis Fortpflanzung, weitere Generationen und gegebenenfalls Ruhezeiten; eine Keimrate allein reicht nicht. Die Heuristik beschreibt keine zielbewusste Entscheidung der Pflanzen und nicht jede Lebenszyklusstrategie vollständig.','C resembles high dispersal/reproductive output and benefits from open land in this model; D shows more individual investment and competitive performance in established vegetation. Changing survival rates reverse advantages. Total fitness requires offspring number, survival to reproduction, subsequent generations and possibly dormancy; germination rate alone is insufficient. The heuristic describes neither deliberate plant choices nor every life-cycle strategy completely.'))
],
[
 case(pair('Eigene Fitnesskurve als Zahlenstützpunkte für ein erbliches Modellmerkmal x=1,2,3,4,5: mittlere Zahl fortpflanzungsfähiger Nachkommen pro Elternteil W=1,3,5,3,1 im vorgegebenen Umfeld. Relative Fitness ist w=W/max(W); Selektionskoeffizient wird hier s=1−w definiert. Keine echte Stichprobe ist behauptet.','Original fitness curve supplied as points for an inherited model trait x=1,2,3,4,5: mean reproductively mature offspring per parent W=1,3,5,3,1 in the specified environment. Relative fitness is w=W/max(W); here the selection coefficient is defined as s=1−w. No real sample is claimed.'),
      pair('Skizziere/interpretiere die Fitnesskurve, berechne w und s für x=1 und x=3 und quantifiziere die gerichtete Benachteiligung im Vergleich. Unterscheide Fitness von Häufigkeit und körperlicher Kraft.','Sketch/interpret the fitness curve, calculate w and s at x=1 and x=3 and quantify relative disadvantage. Distinguish fitness from frequency and physical strength.'),
      pair('Maximum bei x=3; kleinere/größere Extreme haben geringeren mittleren Fortpflanzungserfolg, kompatibel mit stabilisierendem Selektionsdruck im Modell. x=1:w=0,2,s=0,8; x=3:w=1,s=0. Die Definition beschreibt80% geringeren Erfolg relativ zum Maximum, nicht80% individuelle Sterblichkeit. Fitness ist reproduktiver Erfolg unter Bedingungen, die Kurve keine Häufigkeitsverteilung. Veränderung von Merkmalshäufigkeiten benötigt Vererbbarkeit und Generationen; der Modellstützpunkt belegt kein allgemeines Optimum.','The maximum is at x=3; smaller/larger extremes have lower mean reproductive success, compatible with stabilizing selection in the model. At x=1:w=0.2,s=0.8; at x=3:w=1,s=0. This definition expresses80% lower success relative to the maximum, not80% individual mortality. Fitness is conditional reproductive success; the curve is not a frequency distribution. Frequency change requires inheritance and generations; a model point does not establish a universal optimum.')),
 case(pair('Neues synthetisches Umfeld mit x=1,2,3,4,5 und W=5,3,1,3,5. Nach Umweltänderung werden W=1,2,3,4,5 angenommen. Gleiche Definitionen w=W/max(W), s=1−w. Keine Information zur tatsächlichen Ausgangshäufigkeit oder genetischen Architektur.','New synthetic environment with x=1,2,3,4,5 and W=5,3,1,3,5. After environmental change the assumed values are W=1,2,3,4,5. Same definitions w=W/max(W), s=1−w. Actual starting frequencies and genetic architecture are unknown.'),
      pair('Vergleiche Fitnesskurven und Selektionsdruck vor/nach Änderung. Quantifiziere die Benachteiligung von x=3 in beiden Umfeldern und beschränke die daraus ableitbare Populationsprognose.','Compare the curves and selection pressure before/after the change. Quantify the disadvantage of x=3 in both environments and limit the population prediction.'),
      pair('Zuerst zwei bevorzugte Extreme: disruptive Modellfitness, bei x=3 w=0,2/s=0,8. Danach steigende Kurve/gerichtete Bevorzugung großer x; bei x=3 w=0,6/s=0,4. Selektionsdruck ist kontextabhängig. Die Kurve allein zeigt weder sofortige Individuenverwandlung noch sichere Artbildung oder zeitliche Häufigkeiten; Vererbung, Startverteilung, Paarung und andere Evolutionsfaktoren fehlen.','Initially both extremes are favoured: disruptive model fitness; at x=3,w=0.2/s=0.8. Later the curve rises/directionally favours large x; at x=3,w=0.6/s=0.4. Selection pressure is context dependent. The curve alone shows neither instant transformation of individuals nor certain speciation or temporal frequencies; inheritance, starting distribution, mating and other evolutionary factors are unspecified.'))
],
[
 case(pair('Synthetische Vogelbeobachtungen: Ein auffälliger Balzruf führt im Modell häufiger zur Partnerwahl, erhöht aber Entdeckbarkeit durch Räuber. Territorialruf hält Konkurrenten vom Brutplatz fern und kostet Energie. In einer kooperierenden Gruppe wechseln Individuen Wachsamkeit ab, wodurch mehr Fresszeit möglich ist. Es gibt keine Daten zur Verwandtschaft.','Synthetic bird observations: a conspicuous courtship call more often leads to mate choice in the model but increases detection by predators. A territorial call keeps rivals from the nesting site and costs energy. A cooperating group shares vigilance, allowing more feeding time. Relatedness data are absent.'),
      pair('Deute Balz, Territorialität und Kooperation evolutionsbiologisch mit Nutzen/Kosten und Fitness. Trenne funktionale Erklärung von Absicht und unbelegter Verwandtenselektion.','Interpret courtship, territoriality and cooperation evolutionarily using benefits/costs and fitness. Separate functional explanation from intention and unsupported kin-selection claims.'),
      pair('Balz kann direkte Reproduktion fördern, ihr Risiko begrenzt den Nettoeffekt; Territorialität sichert Ressourcen/Brutplätze gegen Energie- und Konfliktkosten. Gegenseitige Wachsamkeit kann direkten Überlebens-/Fortpflanzungsnutzen liefern. Selektion kann erblich beeinflusste Verhaltenstendenzen begünstigen, sofern ihr Gesamterfolg höher ist; Tiere müssen dies nicht beabsichtigen. Ohne Verwandtschafts-/Fortpflanzungsbefunde ist Verwandtenselektion hier keine feststehende Ursache.','Courtship may increase direct reproduction, with risk limiting its net effect; territoriality protects resources/nesting sites against energy and conflict costs. Shared vigilance may provide direct survival/reproductive benefits. Selection may favour heritably influenced behaviour when total success increases; animals need not intend this. Without relatedness/reproduction evidence, kin selection is not an established cause here.')),
 case(pair('Neues synthetisches Fischmodell: größere Balzfarben steigern Paarungschancen, können aber Prädation erhöhen. Kleine Territorien bieten bessere Nahrung, sind jedoch teuer zu verteidigen. Nicht verwandte Individuen jagen manchmal gemeinsam und profitieren jeweils von höherem Fang; Kooperation sinkt bei Ressourcenknappheit.','New synthetic fish model: stronger courtship colours increase mating chances but can raise predation. Small territories provide better food but are costly to defend. Unrelated individuals sometimes hunt together and each benefits from higher capture; cooperation decreases when resources are scarce.'),
      pair('Erkläre alle drei Verhaltensanpassungen und die Änderung bei Knappheit. Nenne Daten, die eine Fitnessdeutung statt einer bloßen Verhaltensbeschreibung prüfen würden.','Explain all three behavioural adaptations and their change under scarcity. Name data testing a fitness interpretation rather than merely describing behaviour.'),
      pair('Balz wirkt über Partnerwahl, Territorialität über Ressourcenzugang, gemeinsame Jagd über gegenseitigen unmittelbaren Nutzen. Knappheit kann Nutzen/Kosten verschieben, sodass Konkurrenz relativ zunimmt; keine Strategie ist moralisch höher oder universal optimal. Prüfen ließen sich Überleben, Fortpflanzungserfolg, Aufwand und Kontext bei vergleichbaren Bedingungen; bloße Farbe/Rufzahl/Fangzahl allein ist keine vollständige Fitness. Die Deutung ist eine begrenzte Hypothese, keine nachgewiesene Evolutionsgeschichte.','Courtship acts through mate choice, territoriality through resource access and joint hunting through immediate mutual benefit. Scarcity can change benefits/costs so competition becomes relatively greater; no strategy is morally superior or universally optimal. Survival, reproductive success, effort and context under comparable conditions could be assessed; colour/call count/capture count alone is not complete fitness. This is a bounded hypothesis, not a proven evolutionary history.'))
],
[
 case(pair('Eigenes Klimaszenario: Ein Gebirgsorganismus benötigt kühle Feuchte. Sein geeigneter Höhenbereich verschiebt sich im Szenario von1000–1600m auf1400–2000m, der lokale Gipfel liegt bei1800m. Zusammenhängendes Habitat wird dadurch kleiner; eine zweite wärmetolerante Art kann tiefer neue Flächen nutzen. Keine tatsächliche regionale Prognose.','Original climate scenario: a mountain organism needs cool moisture. Its suitable range shifts from1000–1600m to1400–2000m in the scenario; the local summit is1800m. Connected habitat becomes smaller, while a second heat-tolerant species can use new lower areas. This is no actual regional forecast.'),
      pair('Bewerte Klimafolgen für beide Arten und das Ökosystem, mögliche Schutzmaßnahmen und Unsicherheit. Begründe, warum „alle Arten wandern einfach nach oben“ nicht genügt.','Evaluate consequences for both species and the ecosystem, possible measures and uncertainty. Explain why all species simply moving uphill is inadequate.'),
      pair('Die kühl-feuchte Art verliert den oberhalb1800m nicht verfügbaren Teil des Klimaraums und möglicherweise Fläche/Vernetzung; die wärmetolerante Art kann lokale Vorteile haben. Veränderte Konkurrenz und Nahrungsbeziehungen wirken auf das System. Vernetzung, Mikrorefugien und zusätzliche Belastungsreduktion können helfen, ersetzen fehlende Gipfel-/Feuchtebedingungen aber nicht. Ausbreitungsfähigkeit, Bodeneignung und Szenarioannahmen begrenzen Vorhersagen; nicht alle Arten reagieren gleich.','The cool/moist species loses suitable range beyond the unavailable1800m summit and may lose area/connectivity; the heat-tolerant species may benefit locally. Changed competition and feeding relationships affect the system. Connectivity, microrefugia and reduced other pressures may help but cannot replace missing elevation/moisture. Dispersal, soil suitability and scenario assumptions limit predictions; species do not all respond alike.')),
 case(pair('Synthetische Zeitfenster: Früher boten Blüten an Tagen100–120 Nahrung und Bestäuber waren an105–125 aktiv. Im Wärmeszenario liegt die Blüte85–105, Bestäuberaktivität bleibt100–120. Auch Wasserknappheit reduziert Blütenzahl. Keine reale Zeitreihe ist gegeben.','Synthetic timing windows: previously flowers offered food on days100–120 and pollinators were active105–125. Under the warming scenario flowering moves to85–105 while pollinator activity remains100–120. Water shortage also reduces flower number. No real time series is provided.'),
      pair('Analysiere die Überlappung als Interaktionsfolge für Arten/Biodiversität und bewerte zwei Handlungsoptionen. Trenne Szenario, mögliche Folgen und nachgewiesene Ursache.','Analyze overlap as an interaction consequence for species/biodiversity and assess two responses. Separate scenario, possible effects and proven cause.'),
      pair('Die zeitliche Überlappung wird kleiner: früher105–120, später100–105 nach dieser Fenstersystematik. Weniger gemeinsame Nahrungs-/Bestäubungszeit kann beide Partner und ihre Nachfolger betreffen; Wasserknappheit verstärkt oder verändert Folgen. Unterschiedlich blühende heimische Pflanzen und geschützte feuchte Mikrohabitate können Puffer bieten, benötigen lokale Eignungs-/Wirkungsprüfung. Aus synthetischen Fenstern folgt kein empirischer Klimakausalnachweis oder zwangsläufiges Aussterben.','Temporal overlap shrinks: formerly105–120, later100–105 under this interval convention. Reduced joint feeding/pollination time may affect both partners and dependent species; water scarcity can strengthen or change effects. Native plants with varied flowering times and protected moist microhabitats may buffer impacts but need local suitability/effect assessment. Synthetic windows establish neither empirical climate causation nor inevitable extinction.'))
],
[
 case(pair('Eigenes Planungsszenario: Eine ehemals heimische Amphibienart fehlt an einem Teich. Ursachen sind Straßenbarriere und fehlende geeignete Laichzonen. Optionen: sofort Tiere freisetzen oder zunächst Barriere/Laichhabitat verbessern, Herkunft/Gesundheit und Genehmigungen prüfen und danach fachlich kontrolliert gegebenenfalls wiederansiedeln. Es gibt keinen tatsächlichen Besatzauftrag.','Original planning scenario: a formerly native amphibian is absent from a pond. Causes include a road barrier and unsuitable spawning habitat. Options: release animals immediately or first improve passage/spawning habitat, check origin/health and permissions and then consider supervised reintroduction. No actual stocking task is authorized.'),
      pair('Plane und bewerte Renaturierung und mögliche Wiederansiedlung als getrennte verbundene Strategien. Lege Entscheidungskriterien und Erfolgskontrolle fest; setze keine Tiere eigenständig frei.','Plan and assess restoration and possible reintroduction as distinct linked strategies. Set decision criteria and monitoring; do not personally release animals.'),
      pair('Renaturierung behebt Ursachen durch geeignete Ufer-/Laichstrukturen und sichere Konnektivität. Erst bei tragfähigem Habitat und begründetem Fehlen natürlicher Wiederbesiedlung wird Wiederansiedlung mit Zuständigkeit, passender Herkunft, genetischen/gesundheitlichen Risiken und Freigaben geprüft. Kontrolle erfasst wiederholte Fortpflanzung/Rekrutierung statt nur ausgesetzte Individuen. Kosten, andere Arten und Verkehrssicherheit sind abzuwägen; Aussetzen ohne Ursachenbehebung ist kein belastbarer Plan.','Restoration addresses causes through suitable bank/spawning structures and safe connectivity. Reintroduction is considered only with viable habitat and justified lack of natural recolonization, appropriate authority/origin and genetic/health risks and permissions. Monitoring tracks repeated reproduction/recruitment rather than just released individuals. Costs, other species and road safety require weighing; release without fixing causes is no sound plan.')),
 case(pair('Neues synthetisches Waldszenario: Eine lokal verschwundene heimische Insektengruppe benötigt ältere Laubbäume und kontinuierlich Totholz. Ein Projekt möchte Jungbäume pflanzen und sofort viele Individuen freisetzen. Alternative: Habitatkontinuität und Verbindung zu Restvorkommen sichern; Wiederansiedlung nur nach Eignungsprüfung.','New synthetic woodland scenario: a locally lost native insect group needs older broadleaf trees and continuous dead wood. A project proposes planting saplings and immediately releasing many individuals. Alternative: retain habitat continuity and connections to remnant populations; consider reintroduction only after suitability assessment.'),
      pair('Erstelle einen stufenweisen Renaturierungs-/Wiederansiedlungsplan, begründe kurzfristige/langfristige Schritte und bewerte den Sofortplan samt Risiken.','Prepare a phased restoration/reintroduction plan, justify short/long-term steps and assess the immediate plan and risks.'),
      pair('Zuerst verbleibende Alt-/Totholzhabitate sichern, Lücken/Vernetzung und Nachlieferung geeigneter Substrate planen; Jungbäume allein liefern nicht sofort den benötigten Entwicklungsraum. Danach natürliche Wiederbesiedlung prüfen und bei Bedarf fachlich genehmigte Wiederansiedlung mit passender Herkunft und Kontrolle planen. Bestehende Arten, Krankheitseintrag und langfristiger Unterhalt gehören zur Bewertung. Erfolg braucht Habitatnutzung und stabile Fortpflanzung über Zeit; eine Freisetzungszahl beweist weder Renaturierung noch Populationserholung.','First protect remaining old/dead-wood habitats and plan continuity/connectivity and future suitable substrate; saplings alone do not immediately supply needed developmental habitat. Then assess natural recolonization and, if justified, plan authorized reintroduction with suitable origin and monitoring. Existing species, disease introduction and long-term maintenance are relevant. Success needs habitat use and sustained reproduction over time; a release count establishes neither restoration nor population recovery.'))
],
[
 case(pair('Eigene Feuchtgebietsoptionen pro Jahr: Erhalt bietet geschätzte Wasserreinigung6000€, Hochwasserverminderung8000€, Erholung4000€; Pflege kostet5000€. Bebauung bringt geschätzte Nettoeinnahmen9000€, beseitigt aber diese Funktionen. Hochwasservorteil und vermeidbarer Flutschaden sind dieselbe Leistung und dürfen nicht doppelt addiert werden. Seltene Arten besitzen zusätzlich nicht vollständig monetarisierbare Werte.','Original wetland options per year: conservation provides estimated water purification€6000, flood reduction€8000 and recreation€4000; care costs€5000. Development provides estimated net income€9000 but removes these functions. Flood protection and avoided flood damage are the same service and must not be added twice. Rare species also have values not fully monetized.'),
      pair('Erfasse die genannten Ökosystemleistungen, berechne eine begrenzte ökonomische Bilanz und bewerte beide Optionen zusätzlich ökologisch. Begrenze die monetäre Entscheidung.','Identify the services, calculate a bounded economic balance and assess both options ecologically as well. Limit the monetary decision.'),
      pair('Wasserreinigung/Hochwasserrückhalt sind regulierende, Erholung eine kulturelle Leistung; das Habitat unterstützt Biodiversität. Erhalt:18000−5000=13000€/Jahr geschätzter Nettowert gegenüber9000€ Bebauungsnetto, soweit gleiche Zeit-/Bilanzgrenzen gelten. Seltene Arten, Funktionszusammenhänge, Verteilung und irreversible Verluste bleiben zusätzlich zu prüfen. Schätzungen, Ersatzbarkeit und mögliche Doppelzählung begrenzen Geldwerte; ein höherer Modellwert ersetzt keine vollständige Werteabwägung oder reale Wirkungsmessung.','Purification/flood retention are regulating services, recreation a cultural service; habitat supports biodiversity. Conservation has estimated annual net value18000−5000=€13000 versus€9000 development net, provided time/accounting boundaries match. Rare species, functional relationships, distribution and irreversible loss require additional assessment. Estimates, replaceability and double counting limit monetary values; a larger model value replaces neither full value deliberation nor real effect measurements.')),
 case(pair('Neues synthetisches Bestäubungsszenario: Ein Blühstreifen kostet2000€/Jahr und kann Ernteverluste geschätzt um3500€/Jahr verringern; die Ernte ist bereits in diesem Schätzwert enthalten. Er erhöht zugleich Habitatverbindungen und Erholung, deren Geldwerte nicht bekannt sind. Eine Intensivierungsoption liefert3000€ zusätzlich, vermindert aber Blühhabitat.','New synthetic pollination scenario: a flower strip costs€2000/year and may reduce estimated crop losses by€3500/year; the harvest is already represented in that estimate. It also improves habitat links and recreation, whose monetary values are unknown. Intensification earns€3000 extra but reduces flowering habitat.'),
      pair('Erfasse Leistungen, analysiere Geld-/ökologische Kriterien und bewerte die Optionen ohne erfundene vollständige Monetarisierung. Nenne einen relevanten Zielkonflikt.','Identify services, analyze monetary/ecological criteria and assess options without fabricated complete monetization. Name a relevant trade-off.'),
      pair('Bestäubung ist regulierend, Erntebereitstellung bereitstellend, Erholung kulturell; Habitatvernetzung hat ökologische Bedeutung. Der bezifferte Streifensaldo ist1500€/Jahr, niedriger als3000€ Intensivierung, aber andere Leistungen/Risiken fehlen im Geldvergleich. Erntewert nicht nochmals als Bestäubungsnutzen addieren. Entscheidung benötigt Gewichtung von Einkommen, Biodiversität, Stabilität und Zugänglichkeit; fehlende Geldwerte sind nicht null und begründen keine automatische Unterlegenheit des Streifens.','Pollination is regulating, crop supply provisioning and recreation cultural; habitat links have ecological significance. The quantified strip balance is€1500/year, below€3000 intensification, but other services/risks are absent from the monetary comparison. Do not add crop value again as pollination benefit. Choice requires weighing income, biodiversity, stability and access; unknown monetary values are not zero and do not automatically make the strip inferior.'))
],
[
 case(pair('Eigenes diskretes Patchmodell pro Jahr: Quelle A hat anfangs100 Individuen, lokal30 Geburten und10 Todesfälle, exportiert20 zu B. Senke B startet mit50, lokal5 Geburten und20 Todesfälle, erhält20 von A. Geeigneter leerer Patch C könnte10 Auswanderer aufnehmen. Keine tatsächliche Migration wird behauptet.','Original discrete yearly patch model: source A starts with100 individuals, locally30 births and10 deaths and exports20 to B. Sink B starts with50, locally5 births and20 deaths and receives20 from A. Suitable empty patch C could receive10 emigrants. No actual migration is claimed.'),
      pair('Modelliere lokale Entwicklung mit/ohne Migration, begründe Quelle/Senke aus Demografie und erläutere die Kolonisationsoption für C. Belegung allein reicht nicht als Kriterium.','Model local development with/without migration, justify source/sink status using demography and explain colonization of C. Occupancy alone is insufficient.'),
      pair('A lokal+20, nach Export100; B lokal−15, mit Immigration55, ohne35. Positive lokale Bilanz macht A zur Quelle, negative B zur Senke; trotz höherem Bestand nach Zuzug ist B keine Quelle. Kolonisation von C braucht geeignete Bedingungen und tatsächliche Ankunft/Fortpflanzung; Umleitung10 nach C reduziert Zufluss zu B und würde B auf45 bringen. Vernetzung, Habitatgüte und externe Verluste bestimmen langfristige Persistenz, nicht bloße Patchfarbe oder ein Jahreswert.','A has local+20 and returns to100 after export; B has local−15, ending at55 with immigration and35 without. Positive local balance makes A a source, negative balance makes B a sink; a larger count after arrival does not make B a source. Colonizing C needs suitable conditions and actual arrival/reproduction; diverting10 to C reduces input to B, which would end at45. Connectivity, habitat quality and external losses determine long-term persistence, not patch colour or a single year.')),
 case(pair('Neues synthetisches Belegungsmodell nach Levins-Form als ausdrücklich gegebenes didaktisches Modell: dp/dt = cp(1−p)−ep, p ist der Anteil geeigneter bewohnter Patches. c=0,6,e=0,2,p=0,5. Eine Barriere senkt c auf0,1. Das Modell unterscheidet keine einzelnen Quellen/Senken.','New synthetic occupancy model supplied as a didactic Levins form: dp/dt = cp(1−p)−ep, p is the fraction of suitable occupied patches. c=0.6,e=0.2,p=0.5. A barrier reduces c to0.1. The model does not distinguish individual sources/sinks.'),
      pair('Nutze das Modell für Kolonisations-/Aussterbedynamik, berechne die Rate und positive Gleichgewichtsbelegung vor/nach Barriere. Verbinde das Ergebnis begrenzt mit Quelle/Senke aus Fall1.','Use the model for colonization/extinction dynamics, calculate the rate and positive equilibrium occupancy before/after the barrier. Relate it cautiously to source/sink dynamics in case1.'),
      pair('Vor Barriere Rate0,6×0,5×0,5−0,2×0,5=0,05; positives Gleichgewicht p*=1−e/c=2/3. Nach Barriere Rate0,025−0,1=−0,075; 1−0,2/0,1=−1 ist kein zulässiger Belegungsanteil, daher kein positives Gleichgewicht. Quellen können Besiedler liefern, Senken Immigration brauchen; diese Unterschiede werden hier homogenisiert. p ist Anteil, keine Individuenzahl; konstante Parameter und gleiche Patchqualität sind Grenzen, nicht gemessene Erfolgsaussagen.','Before the barrier the rate is0.6×0.5×0.5−0.2×0.5=0.05; positive equilibrium p*=1−e/c=2/3. After the barrier the rate is0.025−0.1=−0.075;1−0.2/0.1=−1 is not a valid occupancy fraction, so there is no positive equilibrium. Sources can supply colonizers and sinks need immigration, but these differences are homogenized here. p is a fraction, not individual count; constant parameters and equal patch quality are limitations, not measured success claims.'))
],
[
 case(pair('Eigenes idealisiertes See-Zustandsmodell: Bei steigender äußerer Nährstofflast bleibt der See klar bis Last6, wechselt dann abrupt zum trüben Zustand. Bei sinkender Last bleibt er bis unter Last3 trüb. Last ist ein dimensionsloser Modellindex. Im trüben Zustand fehlen viele Wasserpflanzen, Sediment wird leichter aufgewirbelt und Nährstoffe bleiben stärker verfügbar.','Original idealized lake-state model: with increasing external nutrient load the lake stays clear up to load6 then switches abruptly to turbid. With decreasing load it remains turbid until below3. Load is a dimensionless model index. In the turbid state many aquatic plants are absent, sediment is more easily disturbed and nutrients remain more available.'),
      pair('Erkenne den modellierten Kipppunkt, erläutere Rückkopplung/Hysterese und leite Managementfolgen ab. Behaupte keine echten universellen Schwellenwerte.','Identify the model tipping point, explain feedback/hysteresis and derive management implications. Claim no real universal thresholds.'),
      pair('Die abrupte Zustandsänderung bei6 und andere Rückkehrgrenze bei3 zeigen Modellschwelle/Hysterese. Pflanzenverlust erleichtert Aufwirbelung und Nährstoffverfügbarkeit, was trüben Zustand stabilisieren kann. Frühe Lastreduktion vor Überschreiten ist plausibler als Rückführung erst auf5; Erholung kann deutlich stärkere Entlastung und ergänzende Habitatmaßnahmen benötigen. Schwellen sind ausdrücklich synthetisch; reale Kipp-/Rückkopplungsdiagnose braucht Verlauf, Mechanismus und Alternativursachen, kein einzelnes trübes Foto.','Abrupt change at6 and a different return threshold at3 show model threshold/hysteresis. Plant loss facilitates sediment disturbance and nutrient availability, potentially stabilizing turbidity. Reducing load before crossing is more plausible than merely returning to5 later; recovery may need much stronger relief and additional habitat actions. Thresholds are expressly synthetic; real tipping/feedback diagnosis needs trajectories, mechanisms and alternative-cause assessment, not one turbid photograph.')),
 case(pair('Neues synthetisches Waldmodell: Unter steigender Trockenheitsbelastung sinkt Funktionsindex zunächst100→90→80; jenseits eines Modellbereichs fällt er auf25 und bleibt trotz anschließender leichter Entlastung niedrig. Tote Vegetation erhöht Brennstoffmenge, Brände verringern weitere Vegetation. Vergleichssystem verliert Funktion stetig und erholt sich proportional.','New synthetic woodland model: under increasing drought pressure function first declines100→90→80, then drops to25 beyond a model range and stays low despite slight relief. Dead vegetation increases fuel, and fires remove further vegetation. A comparison system loses function gradually and recovers proportionally.'),
      pair('Vergleiche Schwellenhinweis und stetige Reaktion, erkläre eine mögliche positive Rückkopplung und leite vorsorgliche Management- sowie Datenprüfungen ab.','Compare a threshold indication with a gradual response, explain possible positive feedback and derive precautionary management and data checks.'),
      pair('Abrupter Verlust und verzögerte Rückkehr sind Hinweise auf einen möglichen Zustandswechsel, nicht allein ein Nachweis. Vegetationsverlust→mehr Brennstoff/Feuer→weiterer Verlust kann positive Rückkopplung bilden; Standort, Maßstab und andere Ursachen sind zu prüfen. Stetige proportionale Reaktion braucht keine Kippdiagnose. Management reduziert Belastungen früh, erhält Refugien/Habitatfunktionen und überwacht zeitliche Funktions- und Regenerationsdaten. Keine feste reale Grenzlast oder Erfolgsgarantie folgt aus dem Modell.','Abrupt loss and delayed recovery suggest possible state change but do not establish it alone. Vegetation loss→more fuel/fire→further loss can form positive feedback; site, scale and other causes need assessment. Gradual proportional response needs no tipping diagnosis. Management reduces pressures early, retains refugia/functions and monitors temporal function and regeneration. The model supplies no fixed real threshold or guaranteed success.'))
],
[
 case(pair('Eigene Szenarientabelle, Kriterien vergleichbar definierte Modellpunktwerte0–100: Management U (Uferpuffer) schützt Biodiversität im warm-trockenen Szenario mit70, im gemäßigten mit85; V (reine Einzelpflanzung) mit40 bzw90. Kosten U=8,V=5 Modellbudgeteinheiten. Beide erfüllen gleiche gesetzte Sicherheitsbedingung; keine Wahrscheinlichkeiten für Szenarien.','Original scenario table, criteria defined as comparable model scores0–100: management U (bank buffer) protects biodiversity at70 under warm/dry conditions and85 under moderate conditions; V (single-species planting) at40 and90. Costs are U=8,V=5 model budget units. Both meet the same stipulated safety condition; scenario probabilities are unspecified.'),
      pair('Vergleiche die Optionen unter beiden Szenarien, Kosten und einer vorsorglichen Robustheitsregel. Trenne bedingten Vergleich von Vorhersage und erkläre, welche Gewichte die Wahl verändern.','Compare options under both scenarios, costs and a precautionary robustness rule. Separate conditional comparison from forecasting and explain which weights change the choice.'),
      pair('U ist warm-trocken besser und teurer, V im gemäßigten Szenario etwas besser/günstiger. Nach Maximierung des schlechtesten Schutzwertes gewinnt U(70>40); nach niedrigstem Budget V, soweit Schutzziele erfüllt wären. Ohne Szenariowahrscheinlichkeiten lässt sich kein gewichteter Erwartungswert behaupten. Schutzminimum, Unsicherheit, Kosten und Verteilung müssen transparent priorisiert werden; Modellpunktwerte sind weder echte Artenzahlen noch garantierte Wirkungen.','U is better and more costly in warm/dry conditions; V is slightly better/cheaper under moderate conditions. Maximizing the worst protection score favours U(70>40); minimizing cost favours V if protection requirements are met. Without scenario probabilities no weighted expected value can be claimed. Protection thresholds, uncertainty, cost and distribution require explicit priorities; model scores are neither real species counts nor guaranteed effects.')),
 case(pair('Neues synthetisches Landnutzungsszenario: Korridor K verbindet bestehende Habitate, kostet6 und erreicht Schutzwerte80 bei extensiver sowie60 bei intensiver umgebender Nutzung. Flächenkauf F kostet10 und erreicht75 bzw75. Budget8. Ein zweites Entscheidungsstadium könnte nach Beobachtung zusätzliche Mittel bereitstellen.','New synthetic land-use scenario: corridor K connects existing habitats, costs6 and gives protection scores80 under extensive and60 under intensive surrounding use. Land purchase F costs10 and scores75/75. Budget8. A second decision stage may provide funds after observations.'),
      pair('Vergleiche Managementoptionen anhand Szenario/Budget und entwirf eine adaptive Entscheidung mit überprüfbarem Auslöser. Begründe Grenzen ohne unbekannte Wirkungen zu erfinden.','Compare management options by scenario/budget and propose an adaptive decision with a testable trigger. Justify limitations without inventing unknown effects.'),
      pair('K passt ins aktuelle Budget, F nicht; F ist modellrobuster gegenüber Nutzungsintensität. Eine begründete stufenweise Option ist K mit gesicherter Mindesthabitatqualität, Monitoring der Durchgängigkeit/Nutzung und definiertem Nachsteuerungsbedarf bei schlechterem Schutz als vereinbart. Fördermittel oder F dürfen nicht als schon verfügbar gelten. Grenzwerte, Referenzmessung, externe Nutzungsänderung und Krankheits-/Prädatorenwege sind zu prüfen; Szenarien strukturieren Entscheidungen, bestimmen die Zukunft nicht.','K meets the present budget while F does not; F is more robust to land-use intensity in the model. A justified phased choice could be K with minimum habitat quality, monitoring of connectivity/use and a defined need for adjustment if protection falls below the agreed level. Funding or F must not be treated as already available. Thresholds, reference measurements, external use changes and pathogen/predator pathways need assessment; scenarios structure decisions without determining the future.'))
],
[
 case(pair('Eigenes Funktionsmodell nach gleich starker Störung an Tag0: vor Störung beide Systeme100. A fällt auf60 und erreicht Tag10 wieder95; B fällt nur auf85, bleibt Tag10 bei88. Der Index beschreibt eine festgelegte ökologische Funktion, keine Artenzahl. Nur ein Modellverlauf pro System.','Original functional model after equal disturbance at day0: both systems start at100. A falls to60 and reaches95 at day10; B only falls to85 but stays at88 on day10. The index describes a specified ecosystem function, not species count. Only one model course is supplied per system.'),
      pair('Wende Resistenz und Wiedererholung als klar definierte Resilienzaspekte an. Vergleiche A/B und leite Managementoptionen ab, ohne einen allgemeinen Sieger zu behaupten.','Apply resistance and recovery as explicitly defined resilience aspects. Compare A/B and derive management options without claiming an overall winner.'),
      pair('B hat höhere unmittelbare Resistenz(geringerer Funktionsverlust), A bessere/schnellere Wiedererholung in diesem Zeitfenster. Resilienzbewertung hängt von Funktion, Störung und Zeithorizont ab. Schutz kann unmittelbaren Verlust begrenzen oder Regenerationswege/Refugien fördern; geeignete Funktionsvielfalt und geringere Zusatzbelastung sind zu prüfen. Ein Verlauf beweist weder allgemeine Stabilität noch eine kausale Artenvielfaltswirkung; beide Kriterien und Unsicherheiten bleiben offen.','B has greater immediate resistance(smaller functional loss); A has better/faster recovery over this interval. Resilience assessment depends on function, disturbance and time horizon. Management may limit initial loss or support regeneration/refugia; suitable functional diversity and lower additional pressures need assessment. One course establishes neither general stability nor causal biodiversity effects; both criteria and uncertainties remain relevant.')),
 case(pair('Neues synthetisches Feuchtgebietsmodell: wiederholte Trockenperioden treffen alle4 Wochen ein. System C erreicht frühere Wasserreinigungsfunktion nach2 Wochen, D erst nach6. D besitzt höheres Anfangsniveau, fällt bei erneutem Trockenstress aber vor vollständiger Erholung weiter zurück. Alternative Maßnahmen: Refugien/Vernetzung und verringerte Wasserentnahme oder bloß kosmetische Neubepflanzung.','New synthetic wetland model: drought recurs every4 weeks. C recovers previous water-purification function after2 weeks, D after6. D begins at a higher level but falls further when renewed stress occurs before full recovery. Measures: refugia/connectivity and reduced water withdrawal or only cosmetic replanting.'),
      pair('Analysiere Resilienz bei wiederholter Störung und leite begründete Managementoptionen sowie notwendige Erfolgskriterien ab. Trenne ursprüngliche Höhe, Erholung und Kipppunktnachweis.','Analyze resilience under repeated disturbance and derive justified measures and success criteria. Separate baseline level, recovery and proof of tipping.'),
      pair('C kann im Modell zwischen Störungen erholen, D nicht; ein hohes Anfangsniveau schützt nicht gegen kumulativen Funktionsverlust. Ursachenreduktion der Wasserentnahme und funktionsfähige Refugien/Verbindungen sind plausibler als unpassende dekorative Pflanzen, müssen hydrologisch und biologisch geeignet sein. Monitoring erfasst tatsächliche Wasserreinigungsfunktion, Wasserzustand und Erholungszeiten über mehrere Störungen. Aus langsamem Rückgang allein folgt kein Kipppunkt oder allgemeine Artenzahl-Regel.','C can recover between model disturbances whereas D cannot; a high baseline does not prevent cumulative functional loss. Reducing water withdrawal and maintaining functional refugia/connections is more plausible than unsuitable decorative plants but requires hydrological/biological suitability. Monitoring assesses actual purification function, water conditions and recovery times across repeated disturbances. Slow decline alone establishes neither tipping nor a general species-count rule.'))
],
]

assert len(CASES) == len(goals) == 20
items = []
for n,(g,cases) in enumerate(zip(goals,CASES),1):
    assert len(cases)==2
    for j,c in enumerate(cases,1): c['id']=f'ecology20b-{n:02d}-case-{j}'
    items.append({'goalId':g['id'],'wholeGoal':g,'cases':cases})
materials={'schemaVersion':1,'contract':'whole-current-goal-bilingual-material-and-model-answer-author-v1','authorRole':'author, no independent reviewer','activeWrites':0,'realLearnerEvidence':False,'humanApproval':False,'goals':items}
mp=D/'materials/twenty-whole-goals-forty-complete-DEEN-cases.author.json';mp.parent.mkdir(exist_ok=True);assert not mp.exists();mp.write_text(json.dumps(materials,ensure_ascii=False,indent=2)+'\n')
md=['# Ganze aktuelle Ökologie20b-Ziele: 40 eigene zweisprachige Kandidatenfälle','', 'CC-BY-4.0 – Eigene didaktische Materialien. E1/G1-Kandidaten, keine reale Erhebung oder menschliche Freigabe. Offene Quellenfacetten bleiben HOLD.','']
for item in items:
    g=item['wholeGoal'];md += ['## '+g['title']+' – '+g['id'],'',g['description'],g['descriptionEn'],'']
    for c in item['cases']:
        md += ['### '+c['id'],'']
        for lang in ['de','en']:
            md += ['**'+lang.upper()+' Material:** '+c['material'][lang],'','**Auftrag / Task:** '+c['task'][lang],'','**Muster / Model:** '+c['modelAnswer'][lang],'','**Grenze / Boundary:** '+c['performanceBoundary'][lang],'']
(mp.parent/'twenty-whole-goals-forty-complete-DEEN-cases.author.md').write_text('\n'.join(md)+'\n')
print(json.dumps({'wholeGoals':20,'completeBilingualCases':40,'materialsPath':str(mp.relative_to(ROOT)),'sourceHoldsExcludedFromAnyClosure':True,'activeWrites':0,'realLearnerEvidence':False,'humanApproval':False}))
